files.arith.z-:
fn gcd::(a, b) {
    a = @abs(a); b = @abs(b);
    while (b != 0) { let t = b; b = a % b; a = t; }
    return a;
}
fn lcm::(a, b) {
    if (a == 0 || b == 0) { return 0; }
    return @abs(a * b) / gcd(a, b);
}
fn is_prime::(n) {
    if (n < 2) { return false; }
    if (n % 2 == 0) { return n == 2; }
    let i = 3;
    while (i * i <= n) {
        if (n % i == 0) { return false; }
        i = i + 2;
    }
    return true;
}

