fn strip::(s) {
    let i = 0;
    while (i < @len(s) && @substr(s, i, 1) == " ") { i = i + 1; }
    let j = @len(s);
    while (j > i && @substr(s, j - 1, 1) == " ") { j = j - 1; }
    return @substr(s, i, j - i);
}
fn is_palindrome::(s) {
    let t = @lower(s);
    let r = "";
    let i = @len(t) - 1;
    while (i >= 0) { r = r + @substr(t, i, 1); i = i - 1; }
    return t == r;
}

files.flow.z-:
fn sum::(xs) { let s = 0; for x in xs { s = s + x; } return s; }
fn product::(xs) { let s = 1; for x in xs { s = s * x; } return s; }
fn unique::(xs) {
    let seen = {};
    let out = [];
    for x in xs {
        let k = @str(x);
        if (!@has(seen, k)) { seen[k] = 1; @push(out, x); }
    }
    return out;
}
